package com.renthouse.operation;import com.renthouse.common.api.*;import jakarta.validation.*;import jakarta.validation.constraints.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/v1/agent/properties")public class PropertyController{private final com.renthouse.operation.service.PropertyService s;public PropertyController(com.renthouse.operation.service.PropertyService s){this.s=s;}@PostMapping("/buildings")ApiResponse<String>building(@RequestBody @Valid Building r){return ApiResponse.ok(s.createBuilding(r));}@PostMapping("/units")ApiResponse<String>unit(@RequestBody @Valid Unit r){return ApiResponse.ok(s.createUnit(r));}public record Building(@NotBlank String name,@NotBlank String address){}public record Unit(@Positive long buildingId,@NotBlank String unitNo,@NotBlank String title,@Min(1)int rooms,@Min(0)int halls,@Min(1)int bathrooms,@Positive double areaSqm){}}
